foreach($id in @('22308.143','22308.144')){
  $raw = agent-browser --session bug6931-4382d7d38d88 network request $id --json 2>&1 | Out-String
  try{
    $j = $raw | ConvertFrom-Json
    $pd = $j.data.postData | ConvertFrom-Json
    $rb = $j.data.responseBody | ConvertFrom-Json
    $c0 = $rb.data.categoryList[0].projectList[0].itemList[0].contentId
